function M.human_size(bytes)
  local units = { "B", "KB", "MB", "GB" }
  local value, unit = bytes, 1
  while value >= 1024 and unit < #units do
    value = value / 1024
    unit = unit + 1
  end
  if unit == 1 then
    return ("%d %s"):format(value, units[unit])
  end
  return ("%.1f %s"):format(value, units[unit])
end

